fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if string is empty
    if txt.is_empty() {
        return false;
    }
    
    // Get the last character
    let last_char = txt.chars().last().unwrap(); // safe because we checked is_empty()
    
    // Check if last character is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // Get the length in characters
    let char_count = txt.chars().count();
    
    // If only one character, return true (we already know it's ASCII alphabetic)
    if char_count == 1 {
        return true;
    }
    
    // For multiple characters, get the second-to-last character
    // We can use nth_back(1) to get the character before the last
    let second_last_char = txt.chars().nth_back(1).unwrap(); // safe because char_count >= 2
    
    // Check if second-to-last character is a space
    second_last_char == ' '
}